#!/usr/bin/env bash
# Create Trino's authentication Secrets in the platform namespace (REQ-PLT-11):
#   trino-tls             trino.pem (key + certificate) for HTTPS on 8443, tls.crt
#   trino-auth            password.db: bcrypt entries for the service users admin, superset
#   trino-passwords       TRINO_ADMIN_PASSWORD, TRINO_SUPERSET_PASSWORD (for operators/tools)
#   trino-internal        TRINO_SHARED_SECRET (internal-communication.shared-secret)
# The material is generated by make_secrets.py into deploy/platform/trino/.secrets
# (git-ignored); host clients trust deploy/platform/trino/.secrets/tls.crt.
#
# Idempotent: an existing Secret is kept unless ROTATE=1, so re-running never changes
# credentials behind running clients. After ROTATE=1, restart Trino (make trino-fix).
#
# Usage:  bash deploy/platform/trino/certs.sh [namespace] [python]
set -euo pipefail
NS="${1:-idp-platform}"
PY="${2:-python3}"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OUT="${HERE}/.secrets"
SECRETS=(trino-tls trino-auth trino-passwords trino-internal)

if [ "${ROTATE:-0}" != "1" ]; then
  missing=()
  for s in "${SECRETS[@]}"; do
    kubectl -n "${NS}" get secret "${s}" >/dev/null 2>&1 || missing+=("${s}")
  done
  if [ ${#missing[@]} -eq 0 ]; then
    echo "Trino secrets already exist in ${NS} (ROTATE=1 to regenerate)."
    exit 0
  fi
  if [ ${#missing[@]} -ne ${#SECRETS[@]} ]; then
    echo "ERROR: only some Trino secrets exist (missing: ${missing[*]}); run with ROTATE=1 to regenerate all." >&2
    exit 1
  fi
  ROTATE_FLAG=""
else
  ROTATE_FLAG="--rotate"
fi

"${PY}" "${HERE}/make_secrets.py" "${OUT}" ${ROTATE_FLAG} \
  --name trino.idp-platform.svc --name trino.idp-platform.svc.cluster.local \
  --name trino --name localhost --name 127.0.0.1

apply() { kubectl -n "${NS}" create secret generic "$@" --dry-run=client -o yaml | kubectl apply -f -; }
apply trino-tls --from-file=trino.pem="${OUT}/trino.pem" --from-file=tls.crt="${OUT}/tls.crt"
apply trino-auth --from-file=password.db="${OUT}/password.db"
apply trino-passwords --from-env-file="${OUT}/passwords.env"
apply trino-internal --from-env-file="${OUT}/shared-secret.env"
echo "Trino secrets created in ${NS}; host clients trust ${OUT}/tls.crt"
